INSERT INTO `clients` (`id`, `nom`, `sigle`, `logo`, `contact1`, `contact2`, `email`, `adresse`, `is_entreprise`, `bp`, `point_focal`, `description`, `siteweb`, `facebook`, `linkedin`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Setrag', NULL, 'logo_clients/1bdIfh2PDO5b1nBcqssOC5VYJ6XwCQBgIDynKo5l.png', '1330', NULL, 'c.communication@setrag.com', 'Owendo, LIBREVILLE (GABON)', NULL, '578', NULL, NULL, 'https://setrag.ga/', NULL, NULL, 1, '2025-11-02 23:43:28', '2025-11-03 06:01:25', NULL),
(2, 'ARCEP', 'ARCEP', 'logo_clients/ZB9QRbjF3uvdmdGid8DxYrBKeRLBsjStxOrOkbnY.png', '+24111446811', '+24111446812', 'arcep@arcep.ga', 'Kalikak, Libreville/GABON', NULL, '50000', NULL, '<p>L’<span style=\"font-weight: 700;\">Autorité de Régulation des Communications Électroniques et des Postes</span>&nbsp;(ARCEP) de la République gabonaise est une Autorité administrative indépendante. Elle est créée par l’Ordonnance n°000008/PR/2012 du 13 février 2012 et ratifiée par la loi n° 006/2012 du 13 août 2012 qui abroge le décret n° 0116/PR/MCEN et confère à l’ARCEP la qualité d’«Autorité» en lieu et place d’«Agence», de nouvelles missions et une organisation adaptées au fonctionnement d’une autorité.</p>', 'https://www.arcep.ga/', 'https://www.facebook.com/arcepgabon', NULL, 1, '2025-11-03 06:57:46', '2025-11-03 06:57:46', NULL);
INSERT INTO `commentaires` (`id`, `content`, `commentable_type`, `commentable_id`, `user_id`, `created_at`, `updated_at`) VALUES
(1, 'Tout le monde a la possibilité de modifier les tâches pour ceux qui ont été rajouté dans le services.', 'App\\Models\\Evenement', 5, 13, '2025-09-02 13:00:00', '2025-09-02 13:00:00'),
(2, 'Je viens de lire le description du projet', 'App\\Models\\Projet', 1, 1, '2025-09-02 13:22:01', '2025-09-02 13:22:01'),
(3, 'Toutes les configurations ont été effectuées avec succès, un rapport sera soumis après avoir fini d\'être rédigé.', 'App\\Models\\Tache', 15, 25, '2025-09-08 13:57:18', '2025-09-08 13:57:18'),
(4, 'prière de me partager le contact du M. Larrick. \r\nDe quelles informations a t-il besoin?', 'App\\Models\\Tache', 20, 6, '2025-11-04 07:28:13', '2025-11-04 07:28:13'),
(5, 'je reste en attente de l\'offre technique pour faire l\'offre commerciale', 'App\\Models\\Tache', 19, 6, '2026-01-08 09:17:05', '2026-01-08 09:17:05');
