INSERT INTO `evenements` (`id`, `titre`, `date_debut`, `date_fin`, `lieu`, `statut`, `is_public`, `client_id`, `projet_id`, `description`, `details`, `type_evenement_id`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(3, 'ERIC OVONO', '2025-09-04 11:00:00', '2025-09-04 12:02:00', 'Cité Mébiame', 'prevu', 0, NULL, NULL, NULL, NULL, 1, 6, '2025-09-01 07:03:58', '2025-09-01 07:03:58', NULL),
(5, 'formation Yetu', '2025-09-02 12:20:00', '2025-09-02 17:20:00', 'Visi', 'prevu', 0, NULL, NULL, 'Formation 2 sur Yetu', NULL, 3, 1, '2025-09-02 12:54:15', '2025-10-27 23:22:58', NULL),
(8, 'SAMEAU', '2025-09-18 08:30:00', '2025-09-20 13:00:00', 'Musée National', 'prevu', 1, NULL, NULL, '<p>Stand de présentation de Yubile (Produits et Services)</p>', NULL, 7, 8, '2025-09-16 14:08:44', '2025-09-17 07:20:22', NULL),
(9, 'Reunion de lancement projet Site internet CNEE', '2025-10-22 11:00:00', '2025-10-22 12:30:00', NULL, 'prevu', 1, NULL, NULL, NULL, NULL, 1, 6, '2025-10-19 14:43:27', '2025-10-19 14:43:27', NULL),
(10, 'Présentation YETU à l\'Arcep', '2025-11-03 10:00:00', '2025-11-03 12:00:00', NULL, 'prevu', 0, NULL, 17, '<p>Mail reçu de l\'arcep :&nbsp;</p><p class=\"v1MsoNormal\"><b><span lang=\"FR\" style=\"font-size: 14.0pt\">Bonjour M OPOLO \r\n</span></b></p>\r\n<p class=\"v1MsoNormal\"><span lang=\"FR\">&nbsp;</span></p>\r\n<p class=\"v1MsoNormal\"><span lang=\"FR\" style=\"font-size: 14.0pt\">Dans le\r\n cadre de la mise en œuvre de l\'ensemble des projets de l\'Autorité de \r\nRégulation des Communications Electroniques et des Postes (ARCEP),\r\n</span></p>\r\n<p class=\"v1MsoNormal\"><span lang=\"FR\" style=\"font-size: 14.0pt\">je \r\nviens par le présent mail, d\'une part connaître votre disponibilité dans\r\n les meilleurs délais et d\'autres part, nous présenter un outil de\r\n<b>GESTION MODULABLE ET ADAPTE</b> <b>DE PROJET</b>, conçu</span></p>\r\n<p class=\"v1MsoNormal\"><span lang=\"FR\" style=\"font-size: 14.0pt\">à assister <b>les chefs d\'équipe projet</b> dans les différentes étapes d\'élaboration de leur projet et la collaboration de cet outil avec le comité en charge\r\n</span></p>\r\n<p class=\"v1MsoNormal\"><span lang=\"FR\" style=\"font-size: 14.0pt\">de la gestion du CoPiL</span></p><p><br></p>', NULL, 1, 3, '2025-11-01 15:29:19', '2025-11-04 07:32:23', NULL),
(11, 'Réunion de cadrage site web DGS', '2025-11-05 14:00:00', '2025-11-05 16:00:00', NULL, 'prevu', 1, NULL, NULL, '<p>Mail reçu :&nbsp;</p><div><p>Bonjour Holden,</p>\r\n<p>Suite à notre dernier échange, il était convenu que la DGS vous \r\nadresse un courriel officiel concernant la reprise des activités de \r\nfinalisation des travaux du site web de la DGS.</p>\r\n<p>Nous vous remercions de bien vouloir nous proposer une date afin d\'échanger sur ce sujet.</p>\r\n<p>Cordialement,</p></div><p><br></p>', NULL, 1, 3, '2025-11-01 15:31:26', '2025-11-01 15:31:26', NULL),
(12, 'DGS', '2025-11-03 09:06:00', '2025-11-05 14:30:00', NULL, 'prevu', 0, NULL, 15, NULL, NULL, 1, 8, '2025-11-04 07:07:10', '2025-11-04 07:07:10', NULL);
