INSERT INTO `news` (`id`, `title`, `content`, `created_by`, `image`, `created_at`, `updated_at`) VALUES
(1, 'Mise en ligne de l\'intranet YETU de Yubile', '<p>Une&nbsp;<b>première au Gabon</b>, l\'entreprise Yubile Technologie lance le premier Intranet 100% gabonais.</p><p><span style=\"font-weight: 700;\">Yetu</span>&nbsp;est une solution professionnelle moderne conçue pour répondre aux besoins des organisations publiques et privées (administrations, entreprises, institutions, ONG, etc.).</p><p>Elle centralise et organise efficacement la gestion de l\'information interne ainsi que la relation avec les entités externes (clients, prestataires, partenaires).</p>', 1, 'news_images/ddjrNBdjYBnc3Zu4JTo5uV7P5bb3gS13zAcvfJqK.png', '2025-06-16 13:25:43', '2025-11-03 10:00:15'),
(2, 'test', '<p>test</p>', 6, NULL, '2026-01-15 18:06:49', '2026-01-15 18:06:49'),
(3, 'CNOG', '<p>TEST</p>', 6, NULL, '2026-01-16 09:26:00', '2026-01-16 09:26:00');
