INSERT INTO `projets` (`id`, `nom`, `description`, `priorite_id`, `statut_id`, `client_id`, `created_by`, `date_debut`, `date_fin`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Conception/développement site web BIDZI', 'Créer un site web pour le restaurant <b>BIDZI </b>permettant aux clients de passer des commandes faires des réservations des tables sur ce site,', 3, 2, NULL, 13, '2025-07-14', '2025-10-07', '2025-09-02 08:35:34', '2025-09-03 18:00:53', NULL),
(2, 'Calendrier éditorial de la page TikTok de Yubile', 'Ce calendrier éditorial sera pour période de 3 mois allant de Septembre à Novembre auquel nous trouverons : \r\n- Date de publication\r\n- Contenu \r\n- Objectif du mois \r\n- Format\r\n- Date de validation', 1, 2, NULL, 22, '2025-09-02', '2025-09-05', '2025-09-03 06:52:44', '2025-09-03 06:52:44', NULL),
(3, 'Conception d\'un site web d\'un média de presse en ligne Lacalotte', '<p>L\'objectif de ce projet est de crée site web pour un média de presse en ligne qui est Lacalotte en php et Laravel</p>', 3, 2, NULL, 19, '2025-08-26', '2025-10-25', '2025-09-05 22:57:32', '2025-09-05 22:57:32', NULL),
(4, 'Site web yubilegroupe.com', '<p><span style=\"background-color: rgb(0, 255, 0);\">Conclusion Gagnante</span></p>', 2, 2, NULL, 8, '2025-06-15', '2025-09-30', '2025-09-09 11:13:12', '2025-09-09 11:13:12', NULL),
(5, 'La mise en place d\'un réseau SAMBA', '<p>La mise en place de ce réseau permettra de gérer les matériel informatique de Yubile et les données des utilisateurs ayant différents systèmes.</p>', 1, 3, NULL, 12, '2025-07-21', '2025-08-29', '2025-09-22 10:08:30', '2025-09-22 10:08:30', NULL),
(6, 'Installation d\'un réseau physique', '<p>-Création d\'un réseau en étoile</p><p>-Faire l\'installation des différents&nbsp; serveurs, DNS, serveur Applicatif et serveur de Base de Données</p><p>-Faire une redondance entre les routeurs wifi (CANALBOX et Moov Africa )</p><p><br></p><p><br></p>', 1, 2, NULL, 12, '2025-08-28', '2025-10-31', '2025-10-07 07:24:51', '2025-10-07 07:24:51', NULL),
