(2, 'Relancer DAF CNEE', 'Relancer DAF CNEE pour notre proposition de site CNEE', NULL, 1, 4, 6, '2025-09-02', '2025-09-02', '2025-09-01 11:20:28', '2025-09-02 11:57:56', NULL),
(4, 'Rechercher le top 5 des IA permettant de créer des maquettes et apprendre comment les utilisées pour la création des maquettes', 'Apprendre à créer des maquettes en utilisant des IA.', 1, 1, 4, 13, '2025-08-25', '2025-08-25', '2025-09-02 08:50:49', '2025-09-02 13:20:40', NULL),
(7, 'Dépôt de courrier à la mairie du 1er et du 5 -ème Arrondissement', 'dans le cadre d\'un partenariat public privée avec les mairie pour la digitalisation des service municipaux nous avons déposé un courrier dans les Mairie du 1er et du 5eme Arrondissement de Libreville .', NULL, 2, 4, 11, '2025-09-02', '2025-09-02', '2025-09-02 13:26:55', '2025-09-02 13:26:55', NULL),
(8, 'Petite formation sur l\'IA', 'Apprendre aux autres stagiaires développeurs comment créer des maquettes avec des IA.', NULL, 2, 4, 13, '2025-08-26', '2025-08-26', '2025-09-03 06:35:49', '2025-09-03 06:35:49', NULL),
(9, 'Finalisation de la maquette pour le site de BIDZI', 'Finaliser la maquette de mon projet de soutenance', 1, 3, 4, 13, '2025-08-27', '2025-08-27', '2025-09-03 06:39:23', '2025-09-03 06:39:23', NULL),
(10, 'Structure de la base de donnée', 'Faire la structure de la base de donnée pour le site web BIDZI', 1, 2, 4, 13, '2025-08-28', '2025-09-02', '2025-09-03 06:42:41', '2025-09-03 06:42:41', NULL),
(11, 'Faire la partie administrateur du site BIDZI', 'Faire la partie administratif du site pour gérer les utilisateurs', 1, 3, 5, 13, '2025-09-03', '2025-09-10', '2025-09-03 06:47:29', '2025-12-13 06:24:18', NULL),
(12, 'Calendrier éditorial de la page TikTok', 'calendrier éditorial de la page TikTok sur une période de 3 mois comprenant : \r\n- Date de publication \r\n- Format\r\n- Objectif \r\n- Date de validation\r\n-', 2, 1, 2, 22, '2025-09-02', '2025-09-05', '2025-09-03 06:56:22', '2025-09-03 06:56:22', NULL),
(13, 'Faire des recherches concernant ma thématique ( Conception d’un site pour SNBG)', 'Étudier laravel par des tutos et recherche', NULL, 1, 2, 28, '2025-09-01', '2025-09-02', '2025-09-03 10:32:20', '2025-09-03 10:34:44', NULL),
(15, 'Installation du NPS dans le DC et fin du projet Portail Captive', '<p>Installation et configuration de NPS ( RADIUS) dans le contrôleur de domaine, et Intégration avec PfSense.</p><p>teste des configurations du Portail Captive et la connectivité du Contrôleur du Domaine DC et de PfSense, avec les informations d\'un utilisateur faisant partir du domaine \"yubile.local\".</p>', NULL, 2, 4, 25, '2025-09-05', '2025-09-08', '2025-09-05 07:06:51', '2025-09-08 13:55:49', NULL),
(17, 'Payer billet aller retour pour une mission de présentation du guichet munipal à Moanda', '<p>Payer billet aller retour pour une mission de présentation du guichet municipal à Moanda</p><p>Aller OW-MDA</p><p>Retour FCV-OW</p><p><br></p>', NULL, 2, 1, 8, '2025-09-10', '2025-11-24', '2025-09-06 18:04:50', '2025-11-04 05:57:48', NULL),
(18, 'Actualiser le Devis pour la CNEE', '<p>Actualiser la proposition commercial pour le projet de developpement du site web de la CNEE</p>', NULL, 4, 4, 3, '2025-09-05', '2025-09-08', '2025-09-07 18:13:08', '2025-09-10 14:33:07', NULL),
(19, 'Actualiser l\'offre technique et commercial pour la Comilog', '<p>Apres la rencontre avec la Comilog dans le cadre du projet de deploiement du logiciel PME-Scoring, nous devons actualiser notre offre technique et commerciale pour la réalisation de la plateforme de la Comilog destiné à la publication des appels d\'offre et à l\'interconnexion avec le PME-Scoring</p>', NULL, 4, 4, 3, '2025-09-04', '2026-01-09', '2025-09-07 18:16:24', '2026-01-12 09:54:28', NULL),
(20, 'Envoyer à Mr Larrick toutes les informations Yubile pour la création d\'un compte fournisseur à la Comilog', '<p>Envoyer à Mr Larrick toutes les informations Yubile pour la création d\'un compte fournisseur à la Comilog</p>', NULL, 4, 1, 3, '2025-09-08', '2025-11-24', '2025-09-07 18:17:51', '2025-11-04 05:58:34', NULL),
(21, 'Projet CommercialiZe', '<p>Faire la communication du Produit CommercialiZe</p>', NULL, 2, 1, 8, '2025-09-08', '2025-11-24', '2025-09-09 12:06:56', '2025-11-04 05:59:27', NULL),
(22, 'Zela', '<p>Réunion avec le PCA de la Banque \"La Régionale\" pour le suivi avec la banque et la signature de la convention tripartite.</p>', NULL, 2, 1, 8, '2025-09-08', '2025-11-22', '2025-09-09 12:25:09', '2025-11-04 06:00:01', NULL),
(23, 'CAMI', '<p>Relancer le Business Model de La Ferme KESSALA</p>', NULL, 2, 1, 8, '2025-09-08', '2025-09-15', '2025-09-09 12:29:18', '2025-09-09 12:29:18', NULL),
(24, 'KALAMI', '<p>Rédiger le dossier de préparation adressé à Total afin de négocier les marchés dans le secteur transport ou vente des produits pétroliers</p>', NULL, 2, 1, 8, '2025-09-08', '2025-09-15', '2025-09-09 12:33:13', '2025-09-09 12:33:13', NULL),
(25, 'Clé USB', '<p>Il faut 3 clés USB de 8GB pour l\'installation des serveurs&nbsp;</p>', NULL, 3, 1, 8, '2025-09-01', '2025-09-15', '2025-09-11 08:17:38', '2025-09-11 08:17:38', NULL),
(26, 'Logo Kalami', '<p>Envoyer le logo Kalami</p>', NULL, 3, 1, 8, '2025-09-15', '2025-09-19', '2025-09-17 07:25:42', '2025-09-17 07:25:42', NULL),
(27, 'Yetu', '<p>Envoyer les accès Yetu ANPI</p>', NULL, 4, 1, 8, '2025-09-17', '2025-09-19', '2025-09-17 07:28:07', '2025-09-17 07:28:07', NULL),
(28, 'création du tableau de présence du moi de Septembre 2025', '<p>création du tableau de présence du mois de septembre&nbsp;</p>', NULL, 2, 4, 27, '2025-09-17', '2025-09-17', '2025-09-17 12:10:21', '2025-09-17 12:10:21', NULL),
(43, 'Conception des attestation des stages pour les stagiaires  pour le compte de l\'année 2025', '<p>conception des attestation de stage pour le compte de l\'année 2025</p>', NULL, 2, 3, 27, '2025-09-15', '2025-09-22', '2025-09-18 11:14:17', '2025-09-18 11:14:17', NULL),
(44, 'tableau des salaires envoyer au DG', '<p>le 18 Septembre, le service RH a transmit au DG un tableau EXCEL des salaire&nbsp; &nbsp;</p>', NULL, 2, 4, 27, '0225-09-17', '0225-09-17', '2025-09-18 11:17:44', '2025-09-18 11:17:44', NULL),
(45, 'Creation d\'un fichier PDF pour les salaires des mois de juin et juillet 2025 pour le service RH Et comptabilité', '<p>Création&nbsp; d\'un fichier PDF pour les salaires des mois de juin et juillet 2025, pour le service RH et Comptabilité a fin d\'avoir une traçabilité&nbsp; des agent payer et ceux en attente de paiement&nbsp;&nbsp;</p>', NULL, 2, 2, 27, '2025-09-21', '2025-09-23', '2025-09-18 11:25:53', '2025-09-18 11:25:53', NULL),
(46, 'Zela: Suivi de la convention tripartite', '<p><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Arial;color:#252525;\r\nmso-ansi-language:FR;mso-fareast-language:FR;mso-bidi-language:AR-SA\">Suivi de\r\nla convention tripartite révisée et de la lettre d\'engagement auprès de la\r\nRégionale (DG et DGA, Paulin). **<span style=\"background-color: rgb(255, 0, 0);\">En attente d\'information*</span>&nbsp;</span></p>', NULL, 3, 1, 8, '2025-09-19', '2025-09-25', '2025-09-19 07:36:27', '2025-09-19 07:36:27', NULL),
(47, 'Zela: Poursuite des discussions', '<p><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Arial;color:#252525;\r\nmso-ansi-language:FR;mso-fareast-language:FR;mso-bidi-language:AR-SA\">Poursuite\r\ndes discussions avec le potentiel partenaire financier (DG, DGA, Paulin). <span style=\"background-color: rgb(255, 0, 0);\">*En\r\nattente d\'information**</span></span></p>', NULL, 3, 1, 8, '2025-09-19', '2025-09-25', '2025-09-19 07:38:56', '2025-09-19 07:38:56', NULL),
(48, 'KALAMI', '<p>Envoyer le logo Kalami</p>', NULL, 4, 1, 8, '2025-09-15', '2025-09-20', '2025-09-19 07:41:51', '2025-09-19 07:41:51', NULL),
(49, 'Zela: Demande', '<p><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Arial;color:#252525;\r\nmso-ansi-language:FR;mso-fareast-language:FR;mso-bidi-language:AR-SA\">Demande\r\nde garantie bancaire et suivi de l\'obtention du document (DG, DGA, Paulin). <span style=\"background-color: rgb(255, 0, 0);\">*En\r\nattente d\'information**&nbsp;</span></span></p>', NULL, 1, 1, 8, '2025-09-19', '2025-09-25', '2025-09-19 07:43:32', '2025-09-19 07:43:32', NULL),
(50, 'Zela: Réaménagement des DQE', '<p><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Arial;color:#252525;\r\nmso-ansi-language:FR;mso-fareast-language:FR;mso-bidi-language:AR-SA\">Réaménagement des DQE au prix du marché (Architecte et et Ingénieur). <span style=\"background-color: rgb(255, 0, 0);\">*En\r\ncours*&nbsp;</span></span></p>', NULL, 3, 2, 8, '2025-09-19', '2025-09-25', '2025-09-19 07:44:46', '2025-09-19 07:44:46', NULL),
(51, 'Zela: Présentation des DQE', '<p><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Arial;color:#252525;\r\nmso-ansi-language:FR;mso-fareast-language:FR;mso-bidi-language:AR-SA\">Présentation\r\ndes DQE: Séparation des coûts des matériels et des ceux de la main d\'œuvre\r\n(Archi, ingénieur, coordo en appui). <span style=\"background-color: rgb(255, 0, 0);\">*En cours*&nbsp;</span></span></p>', NULL, 3, 2, 8, '2025-09-19', '2025-09-25', '2025-09-19 07:47:47', '2025-09-19 07:47:47', NULL),
(52, 'Faire un catalogue du matériel de Yubile', '<p>-S\'occuper du matériel&nbsp;</p><p>-Analyser le matériel&nbsp;</p><p>-Vérifier si chaque ordinateur possède un compte utilisateur&nbsp;</p>', NULL, 1, 4, 12, '2025-06-18', '2025-06-25', '2025-09-22 09:19:53', '2025-09-22 09:19:53', NULL),
(53, 'Configuration du répéteur', '<p>Rétablir la connexion&nbsp;</p>', NULL, 1, 4, 12, '2025-09-04', '2025-09-04', '2025-09-22 09:46:44', '2025-09-22 09:46:44', NULL),
(54, 'Installation de l\'hyperviseur de type 1 (PROXMOX)', '<p>L\'hyperviseur de type 1 qui PROXMOX est le moyen, par lequel nous pourrons exécuter et coordonner les machines virtuelles</p>', 6, 1, 4, 12, '2025-09-16', '2025-09-16', '2025-10-07 08:06:09', '2025-10-07 08:06:09', NULL),
(55, 'Organiser une campagne de prospection (Emailing) pour le produit Yetu', '<p>Sur la base du target market de yetu, trouver les entreprises cibles idéales, réaliser les accroches en vue d\'obtenir des RDV&nbsp; et réaliser des ventes sur le produit</p><p><br></p>', 17, 2, 2, 15, '2025-10-23', '2025-11-05', '2025-10-23 09:10:57', '2025-11-03 07:13:12', NULL),
(56, 'PLUBICATION DES ANNONCES COMMERCIALES SUR LA PLATEFORME', '<p><b>La publication des annonces sur la plateforme kaakuni est une étape qui permets aux concepteurs de l\'application de faire une auto évaluation des fonctionnalités de la plateforme, elle permet également aux utilisateurs d\'avoir une claire voyance sur les offres commerciales publiées et une crédibilité des bienfaits de l\'application.</b></p>', 18, 3, 2, 10, '2025-10-10', '2025-11-30', '2025-10-30 10:57:33', '2025-10-30 10:57:33', NULL);
INSERT INTO `tache_confirmations` (`id`, `tache_id`, `confirmed_by`, `comment`, `confirmed_at`, `validated_by`, `validated_at`, `validation_status`, `validation_comment`, `created_at`, `updated_at`) VALUES
(1, 2, 6, 'Bonjour DAF.\r\n\r\n​Je vous prie de bien vouloir excuser mon retard de réponse.\r\n\r\n​Nous sommes actuellement en phase de prospection pour la sélection de prestataires qui nous accompagneront dans la création du site Internet du CNEE.\r\n\r\n​L\'entreprise YUBILE TECHNOLOGIE a effectivement soumis une proposition. \r\n\r\nCependant, le projet est toujours en cours d\'évaluation et aucune décision n\'a encore été prise. \r\n\r\nNous sommes en train de revisiter le cahier des charges du site Internet. Avant de le soumettre au DG.', '2025-09-02 11:57:56', NULL, NULL, 'pending', NULL, '2025-09-02 11:57:56', '2025-09-02 11:57:56'),
(3, 1, 6, 'oui', '2025-09-03 09:39:22', NULL, NULL, 'pending', NULL, '2025-09-03 09:39:22', '2025-09-03 09:39:22'),
(4, 19, 3, 'Mail envoyé à la COMILO contenant le cahier de charge revu, l\'offre technique et le devsi', '2026-01-12 09:54:28', NULL, NULL, 'pending', NULL, '2026-01-12 09:54:28', '2026-01-12 09:54:28');
